def _yaml_to_json(yamlPath):
    try:
        with open(yamlPath, encoding="utf-8") as f:
            datas = yaml.load(f, Loader=yaml.FullLoader)
        jsonDatas = json.dumps(datas, indent=5)
        return jsonDatas
    except Exception as e:
        logger.info("Read Kubeconfig File Fail.")
        logger.info(e)


def _write_string_to_file(filePath, dataString):
    try:
        with open(filePath, 'w') as f:
            f.write(dataString)
            f.close()
        time.sleep(5)
    except Exception as e:
        logger.info("write Kubeconfig json File Fail.")
        logger.info(e)


def _read_template_file_to_string(planTemplatename):
    if not os.path.isfile(planTemplatename):
        logger.info("can not open the template file: {}".format(planTemplatename))
        return " "
    with open(planTemplatename, "r") as f:
        templatefile = f.read()
    return templatefile


def Kubeyaml_to_kubejson_file(cloudID, yamlFilePath, jsonFilePath):
    """
    Transfer OE kubeconfig yaml file to netact kubeconfig json file

    _*Parameters:*_
    | Input Parameters | Man. | Description                             |
    | cloudID          | Yes  | testline id or MRBTS id, must be digit  |
    | yamlFilePath     | Yes  | input YAML kebuconfig file              |
    | jsonFilePath     | Yes  | output json kubeconfig file             |

    _*Return Value:*_
    | Return Value | No Return value    |

    _*Example:*_
    | ${cloudID}           | "12345"                             |
    | ${yamlFilePath}      | "/home/ute/json/config"             |
    | ${jsonFilePath}      | "/home/ute/json/kubejsontest.json"  |
    | Kubeyaml_to_kubejson_file    | ${cloudID}  | ${yamlFilePath} | ${jsonFilePath}  |

    """

    kubejsonstring = """{
    "managedObjects": [{
    "moId": "PLMN-PLMN/CLOUD-cloudid/K8SAPI-1/KUBECONFIG-1",
    "moClass": {
      "id": "com.nokia.netact.lcm.ssd:KUBECONFIG",
      "version": "1.0"
    },
    "planOperation": "CREATE",
    "parameters": kubeconfigjson
    }]
    }"""
    kubeyaml = _yaml_to_json(yamlFilePath)
    kubejsonstring = kubejsonstring.replace("cloudid", str(cloudID))
    kubejsonstring = kubejsonstring.replace("kubeconfigjson", kubeyaml)
    fulljsonFilePath = jsonFilePath + "/" + "kubejsontest.json"
    _write_string_to_file(fulljsonFilePath, kubejsonstring)
    return fulljsonFilePath


def create_secret_json_file(secretname, psk, refnum, secretfilepath):
    """
    Create CMP secret SSD file

    _*Parameters:*_
    | Input Parameters | Man. | Description                             |
    | secretname       | Yes  | secret name for netact                  |
    | psk              | Yes  | CMP server Pre-shared key               |
    | refnum           | Yes  | CMP server Reference number             |
    | secretfilepath   | Yes  | store SSD file path                     |

    _*Return Value:*_
    | Return Value | No Return value    |

    _*Example:*_
    | ${secretname}     | "secret12345"                    |
    | ${psk}            | "X2gd-4PJa-QLo2-rk9k"            |
    | ${refnum}         | "56215"                          |
    | ${secretfilepath }  | "/home/ute/json  |
    | create_secret_json_file    | ${secretname}  | ${psk} | ${refnum} | ${secretfilepath} /

    """

    secret_string = """{
  "managedObjects": [
    {
      "moId": "PLMN-PLMN/SECRET-secretName",
      "moClass": {
        "id": "com.nokia.netact.lcm.ssd:SECRET",
        "version": "1.0"
      },
      "planOperation": "CREATE",
      "parameters": {
        "apiVersion": "v1",
        "kind": "Secret",
        "metadata": {
          "name": "secretName"
        },
        "type": "Opaque",
        "stringData": {
          "psk": "pskstring",
          "refnum": "refnumber"
        }
      }
    }
  ]
}"""
    secret_string = secret_string.replace("secretName", secretname)
    secret_string = secret_string.replace("pskstring", psk)
    secret_string = secret_string.replace("refnumber", refnum)
    logger.info(secret_string)
    secretfile = secretfilepath + "/" + secretname.strip() + ".json"
    _write_string_to_file(secretfile, secret_string)
    return secretfile


def create_netact_deploy_plan(storeplanpath, productname, deployplanname, cloudid,
                              swversion, namespace, clusterchart, clusterbase64,
                              prerequisitechart, prerequisitebase64, mainchart, mainbase64, secretname):
    """
    Create VCU/VDU netact maunal deploying paln file

    _*Parameters:*_
    | Input Parameters    | Man. | Description                                            |
    | planTemplatename    | Yes  | Plan template file, full path                          |
    | storeplanpath       | Yes  | Store path for generating netact deploy plan file      |
    | productname         | Yes  | "vcu" / "vdu",                                         |
    | deployplanname      | Yes  | the name for deploying plan                            |
    | cloudid             | Yes  | testline id or MRBTS id                                |
    | swversion           | Yes  | vcu/vdu package version info                           |
    | namespace           | Yes  | OE namespace name for installing vcu/vdu               |
    | clusterchart        | Yes  | cluster chart name in current vcu/vdu SW version       |
    | clusterbase64       | Yes  | cluster parameter file base64 string                   |
    | prerequisitechart   | Yes  | prerequisite chart name in current vcu/vdu SW version  |
    | prerequisitebase64  | Yes  | prerequisite parameter file base64 string              |
    | mainchart           | Yes  | main chart name in current vcu/vdu SW version          |
    | mainbase64          | Yes  | main parameter file base64 string                      |
    | secretname          | Yes  | secret SSD name that have upload to netact             |

    _*Return Value:*_
    | Return Value | Return Ture when success, otherwise reutrn False |

    _*Example:*_
    | ${planTemplatename}    | "/home/ute/templateplan/ManualDeployPlanTemplate.xml"   |
    | ${storeplanpath}       | "/home/ute/templateplan"                                |
    | ${productname}         | "vcu"                                                   |
    | ${deployplanname}      | "vcu_123456_plan"                                       |
    | ${cloudid}             | "123456"                                                |
    | ${swversion}           | "vCUCNF00_0.250.12912"                                  |
    | ${namespace}           | "cran1"                                                 |
    | ${clusterchart}        | "aic-vcu-cluster-preparation-17.402.1.tgz"              |
    | ${clusterbase64}       | "clusterbase64"                                         |
    | ${prerequisitechart}   | "aic-vcu-prerequisite-18.556.3.tgz"                     |
    | ${prerequisitebase64}  | "prerequisitebase64"                                    |
    | ${mainchart}           | "aic-vcu-0.250.12912.tgz"                               |
    | ${mainbase64}          | "mainbase64"                                            |
    | ${secretname}          | "secret123456"                                          |
    | create_netact_deploy_plan | ${planTemplatename}  | ${storeplanpath} | ${productname} | ${deployplanname} | ${cloudid} |
                                | ${swversion}  | ${namespace} | ${clusterchart} | ${clusterbase64} | ${prerequisitechart} |
                                | ${prerequisitebase64}  | ${mainchart} | ${mainbase64} | ${secretname} |

    """
    templatestring = _get_scfplan_template_string()
    if len(templatestring) < 5:
        logger.info("can not read the template file: {}".format(planTemplatename))
        return ""
    if not os.path.exists(storeplanpath):
        logger.info("there are not the storing path: {}".format(storeplanpath))
        return ""
    logger.info("The plan storing path is {}".format(storeplanpath))
    templatestring = templatestring.format(planname=deployplanname, cloudid=cloudid, swversion=swversion, productname=productname,
                                           namespacestring=namespace, clusterchart=clusterchart, clusterbase64=clusterbase64,
                                           prerequisitechart=prerequisitechart, prerequisitebase64=prerequisitebase64,
                                           mainchart=mainchart, mainbase64=mainbase64, secretname=secretname)
    logger.info(templatestring)
    storename = storeplanpath + """/""" + deployplanname.strip() + """.xml"""
    logger.info(storename)
    _write_string_to_file(storename, templatestring)
    return storename


def create_netact_terminate_plan(storeplanpath, terminateplanname, cloudid):
    """
    Create VCU/VDU netact terminate paln file

    _*Parameters:*_
    | Input Parameters    | Man. | Description                                            |
    | planTemplatename    | Yes  | Plan template file, full path                          |
    | storeplanpath       | Yes  | Store path for generating netact deploy plan file      |
    | terminateplanname   | Yes  | the name for terminate plan                            |
    | cloudid             | Yes  | testline id or MRBTS id                                |

    _*Return Value:*_
    | Return Value | Return Ture when success, otherwise reutrn False |

    _*Example:*_
    | ${planTemplatename}    | "/home/ute/templateplan/TerminatePlanTemplate.xml"      |
    | ${storeplanpath}       | "/home/ute/templateplan"                                |
    | ${terminateplanname}   | "terminate_123456_plan"                                 |
    | ${cloudid}             | "123456"                                                |
    | create_netact_terminate_plan | ${planTemplatename}  | ${storeplanpath} | ${terminateplanname} | ${cloudid} |

    """
    templatestring = _get_terminateplan_template_string()
    if len(templatestring) < 5:
        logger.info("can not read the template")
        return ""
    if not os.path.exists(storeplanpath):
        logger.info("there are not the storing path: " + storeplanpath)
        return ""
    logger.info("The plan storing path is " + storeplanpath)
    templatestring = templatestring.format(terminatename=terminateplanname, cloudid=cloudid)
    logger.info(templatestring)
    storename = storeplanpath + """/""" + terminateplanname + """.xml"""
    logger.info(storename)
    _write_string_to_file(storename, templatestring)
    return storename


def _uncompress_tar_file(filename, uncompresspath):
    if os.path.isfile(filename):
        with tarfile.open(filename, 'r') as f:
            f.extractall(uncompresspath)
    else:
        return False
    return True


def _download_yaml_conversion_tool(swversion, temppath, artifactory_location="HZ"):
    try:
        if os.path.exists(temppath):
            shutil.rmtree(temppath)
        os.makedirs(temppath)
        artifactory_url = artifactory._get_artifactory_url_for_location(artifactory_location)
        tempstring = artifactory_url + """/artifactory/mnp5g-central-public-remote/System_Release/"""
        wgetpathurl = tempstring + """{0}/{1}/artifacts/conversionApp-{2}.tar.gz"""
        wgetoutpath = temppath + """/conversionApp-{0}.tar.gz"""
        swversionlist = swversion.split('_')
        versionnmuber = swversionlist[1].strip()
        productrelease = swversionlist[0].strip()
        wgetpathurl = wgetpathurl.format(productrelease, swversion, versionnmuber)
        wgetoutpath = wgetoutpath.format(versionnmuber)
        logger.info(wgetpathurl)
        file_name = artifactory._download_file_from_artifactory(wgetpathurl, wgetoutpath)
        time.sleep(2)
        logger.info(file_name)
        return file_name
    except Exception as e:
        logger.info("can not download conversion tool")
        logger.info(e)
        return ""


def get_conversion_tool(swversion, toolpath, artifactory_location="HZ"):
    """
    Download and uncompress conversion tool

    _*Parameters:*_
    | Input Parameters     | Man. | Description                              |
    | productname          | Yes  | product name vcd/vdu                     |
    | swversion            | Yes  | product package version, vcu/vdu version |
    | toolpath             | Yes  | store conversion tool path, carefully    |
    | artifactory_location | No   | prefered artifactory server [HZ|ESP]     |

    _*Return Value:*_
    | Return Value | Return Ture when success, otherwise Return False    |

    _*Example:*_
    | ${swversion}       | "vCUCNF00_0.250.13351"    |
    | ${toolpath}        | "/home/ute/yamltemp"      |
    | get_conversion_tool    | ${swversion} | ${temppath} |

    """
    unique_id = time.strftime("%Y%m%d_%H%M%S", time.localtime())
    currenttoolpath = os.path.join(toolpath, unique_id)
    temppath = os.path.join(currenttoolpath, "conversiontool")
    conversiontoolname = _download_yaml_conversion_tool(swversion, temppath, artifactory_location)
    if _uncompress_tar_file(conversiontoolname, temppath):
        gzfilepath = temppath + """/conversionApp"""
        logger.info(gzfilepath)
        files = os.listdir(gzfilepath)
        for file in files:
            logger.info(file)
            if file.endswith('gz'):
                gzfile = gzfilepath + """/""" + file
                logger.info(gzfile)
                _uncompress_tar_file(gzfile, gzfilepath)
                return currenttoolpath
    else:
        return None


def conversion_yaml_file(toolpath, oldyamlfile, yamlstyle, productname):
    """
    Conversion old version yaml file to current version yaml file
    the keyword need to use with get_conversion_tool keyword together
    the current yaml file name oldyamlfile + "_new"
    Note:
    aic-vcu-cluster-preparation-17.402.1.tgz  "cluster"
    aic-vcu-prerequisite-18.556.3.tgz         "prerequisite"
    aic-vcu-0.250.12912.tgz                   " "

    _*Parameters:*_
    | Input Parameters | Man. | Description                                                          |
    | toolpath         | Yes  | conversion tool store path,same with temppath in get_conversion_tool |
    | oldyamlfile      | Yes  | input old version yaml file                                          |
    | yamlstyle        | Yes  | which chart parameter file, "cluster"/"prerequisite"/""              |
    | productname      | Yes  | product name vcd/vdu                     |
    _*Return Value:*_
    | Return Value | Return current yaml file name    |

    _*Example:*_
    | ${toolpath}        | "/home/ute/yamltemp"                                 |
    | ${oldyamlfile}     | "/home/ute/yamlfile/values-override.aic-vcu.yaml"    |
    | ${yamlstyle}       | " "                                                  |
    | ${productname}     | vcu                                                  |
    | conversion_ymal_file | ${toolpath}  | ${oldyamlfile} | ${yamlstyle} |  ${productname} /

    """
    temppath = os.path.join(toolpath, "conversiontool")
    checkstyle = yamlstyle.strip().lower()
    application = temppath + """/conversionApp/cnf_userinput_conversion"""
    newyamlfile = oldyamlfile.strip() + """_new"""
    if os.path.isfile(newyamlfile):
        os.remove(newyamlfile)
    command = """{application} -s {oldyamlfile} -t {template} -o {newyamlfile}"""
    tool_style = productname.strip().lower()
    if checkstyle == 'cluster':
        templatefile = temppath + "/conversionApp/values-override.aic-{0}-cluster-preparation.tpl".format(tool_style)
    elif checkstyle == 'prerequisite':
        templatefile = temppath + "/conversionApp/values-override.aic-{0}-prerequisite.tpl".format(tool_style)
    else:
        templatefile = temppath + "/conversionApp/values-override.aic-{0}.tpl".format(tool_style)
    command = command.format(application=application, oldyamlfile=oldyamlfile, template=templatefile, newyamlfile=newyamlfile)
    logger.info(command)
    os.system(command)
    return newyamlfile


def delete_conversion_tool(toolpath):
    """
    :param toolpath:
    :return: No return
    """
    if os.path.exists(toolpath):
        shutil.rmtree(toolpath)


def _get_encode_base64(yamlfile):
    ori_info = _read_template_file_to_string(yamlfile)
    base64_info = base64.b64encode(ori_info.encode('utf-8'))
    return base64_info.decode()


def create_vcu_vdu_scfplan_file(toolpath, testlinepath, deployplanname, cloudid,
                                swversion, namespace, clusterchart, clusteryaml,
                                prerequisitechart, prerequisiteyaml, mainchart,
                                mainyaml, secretname, productname, artifactory_location="HZ"):
    try:
        tool_path = get_conversion_tool(swversion, toolpath, artifactory_location)
        logger.info(tool_path)
        product_name_lower = productname.strip().lower()
        new_clusteryaml = conversion_yaml_file(tool_path, clusteryaml, "cluster", product_name_lower)
        new_prerequisiteyaml = conversion_yaml_file(tool_path, prerequisiteyaml, "prerequisite", product_name_lower)
        new_mainyaml = conversion_yaml_file(tool_path, mainyaml, " ", product_name_lower)
        clusterbase64 = _get_encode_base64(new_clusteryaml)
        prerequisitebase64 = _get_encode_base64(new_prerequisiteyaml)
        mainbase64 = _get_encode_base64(new_mainyaml)
        result = create_netact_deploy_plan(testlinepath, product_name_lower, deployplanname, cloudid,
                                           swversion, namespace, clusterchart, clusterbase64,
                                           prerequisitechart, prerequisitebase64, mainchart, mainbase64, secretname)
    except Exception as e:
        logger.info("create the scf plan fail")
        logger.info(e)
    finally:
        delete_conversion_tool(tool_path)
    return result


def create_modn_name(mrbtsid):
    modnname = "PLMN-PLMN/CNF-{}".format(mrbtsid)
