def _get_pnp_scf_part_string(pnpscffile, swversion):
    temppnpscfstring = _read_template_file_to_string(pnpscffile)
    temppnpscfstring = temppnpscfstring.format(swversion=swversion)
    return temppnpscfstring


def update_pnp_yaml_for_cmpserver(pnpyamlfile, netactlink, secretname, cmpip, cmpport, caname, eename,
                                  additionalta=''):
    temppnpyamlstring = _read_template_file_to_string(pnpyamlfile)
    try:
        temppnpyamlstring = temppnpyamlstring.replace("{netactlink}", netactlink)
        temppnpyamlstring = temppnpyamlstring.replace("{secretname}", secretname)
        temppnpyamlstring = temppnpyamlstring.replace("{cmpip}", cmpip)
        temppnpyamlstring = temppnpyamlstring.replace("{cmpport}", cmpport)
        temppnpyamlstring = temppnpyamlstring.replace("{caname}", caname)
        temppnpyamlstring = temppnpyamlstring.replace("{eename}", eename)
        temppnpyamlstring = temppnpyamlstring.replace("{additionalta}", additionalta)
        logger.info("the main yaml file {0}".format(temppnpyamlstring))
        newyamlfile = pnpyamlfile.strip() + """_update"""
        logger.info("the main yaml file name {0}".format(newyamlfile))
        _write_string_to_file(newyamlfile, temppnpyamlstring)
    except Exception as e:
        logger.info("create the yaml file fail")
        logger.info(e)
        return False
    return True


def create_pnp_vcu_vdu_scfplan_file(toolpath, testlinepath, deployplanname, cloudid,
                                    swversion, namespace, clusterchart, clusteryaml,
                                    prerequisitechart, prerequisiteyaml, mainchart, mainyaml, secretname,
                                    pnpscffile, productname, additionalta=None, artifactory_location="HZ"):
    try:
        tool_path = get_conversion_tool(swversion, toolpath, artifactory_location)
        logger.info(tool_path)
        product_name_lower = productname.strip().lower()
        new_clusteryaml = conversion_yaml_file(tool_path, clusteryaml, "cluster", product_name_lower)
        new_prerequisiteyaml = prerequisiteyaml
        updatemainyaml = mainyaml.strip() + """_update"""
        new_mainyaml = conversion_yaml_file(tool_path, updatemainyaml, " ", product_name_lower)
        clusterbase64 = _get_encode_base64(new_clusteryaml)
        prerequisitebase64 = _get_encode_base64(new_prerequisiteyaml)
        mainbase64 = _get_encode_base64(new_mainyaml)
        pnpscfpartstring = _get_pnp_scf_part_string(pnpscffile, swversion)
        result = create_pnp_netact_deploy_plan(testlinepath, product_name_lower, deployplanname, cloudid,
                                               swversion, namespace, clusterchart, clusterbase64,
                                               prerequisitechart, prerequisitebase64, mainchart, mainbase64,
                                               secretname, pnpscfpartstring, additionalta)
    except Exception as e:
        logger.info("create the scf plan fail")
        logger.info(e)
    finally:
        delete_conversion_tool(tool_path)
    return result


def create_pnp_netact_deploy_plan(storeplanpath, productname, deployplanname, cloudid,
                                  swversion, namespace, clusterchart, clusterbase64,
                                  prerequisitechart, prerequisitebase64, mainchart, mainbase64,
                                  secretname, pnpscfstring, additionaltaname=None):
    templatestring = _get_pnp_scfplan_template_string()
    if len(templatestring) < 5:
        logger.info("can not read the template file: {}".format(planTemplatename))
        return ""
    if not os.path.exists(storeplanpath):
        logger.info("there are not the storing path: {}".format(storeplanpath))
        return ""
    if additionaltaname is None:
        tempsecretname = secretname
    else:
        tempsecretname = secretname + """</p>\n        <p>""" + additionaltaname
    logger.info("The plan storing path is {}".format(storeplanpath))
    templatestring = templatestring.format(planname=deployplanname, cloudid=cloudid, swversion=swversion, productname=productname,
                                           namespacestring=namespace, clusterchart=clusterchart, clusterbase64=clusterbase64,
                                           prerequisitechart=prerequisitechart, prerequisitebase64=prerequisitebase64,
                                           mainchart=mainchart, mainbase64=mainbase64, secretname=tempsecretname, pnpscfpart=pnpscfstring)
    logger.info(templatestring)
    storename = storeplanpath + """/""" + deployplanname.strip() + """.xml"""
    logger.info(storename)
    _write_string_to_file(storename, templatestring)
    return storename


def create_additionalta_json_file(additionaltaname, pemkeyfile, namespace, additionaltapath):
    secret_string = """{"managedObjects":[
    {"moId":"PLMN-PLMN/SECRET-{{additionalta}}",
    "moClass":{
    "id":"com.nokia.netact.lcm.ssd:SECRET",
    "version":"1.0"},
    "planOperation":"CREATE",
    "parameters":{
    "apiVersion":"v1",
    "data":{
    "additional_tacert":"{{pemkey}}"},
    "kind":"Secret",
    "metadata":{"name":"{{additionalta}}","namespace":"{{namespace}}"},
    "type":"Opaque"}
    }]}"""
    pemkeystring = _get_encode_base64(pemkeyfile)
    secret_string = secret_string.replace("{{additionalta}}", additionaltaname)
    secret_string = secret_string.replace("{{pemkey}}", pemkeystring)
    secret_string = secret_string.replace("{{namespace}}", namespace)
    logger.info(secret_string)
    secretfile = additionaltapath + "/" + additionaltaname.strip() + ".json"
    _write_string_to_file(secretfile, secret_string)
    return secretfile


def create_ccr_key_info(lcminfo, adminpassword):
    totalstring = """{"auths":{"{lcminfo}:8443":{"username":"admin","password":"{adminpassword}","auth":"{base64string}"}}}"""
    tempstring = "admin:{0}".format(adminpassword)
    base64_info = base64.b64encode(tempstring.encode('utf-8'))
    base64string = base64_info.decode()
    totalstring = totalstring.replace("{lcminfo}", lcminfo)
    totalstring = totalstring.replace("{adminpassword}", adminpassword)
    totalstring = totalstring.replace("{base64string}", base64string)
    base64_total = base64.b64encode(totalstring.encode('utf-8'))
    pemkey = base64_total.decode()
    return pemkey


def create_vdu_ccr_secret_json_file(ccr_name, namespace, lcminfo, adminpassword, ccrpath):
    secret_string = """{
    "managedObjects": [
    {
    "moId": "PLMN-PLMN/SECRET-{ccr_name}",
    "moClass": {
    "id": "com.nokia.netact.lcm.ssd:SECRET",
    "version": "1.0"
    },
    "planOperation": "CREATE",
    "parameters": {
    "apiVersion": "v1",
    "data": {
    ".dockerconfigjson": "{base64string}"
    },
    "kind": "Secret",
    "metadata": {
    "name": "{ccr_name}",
    "namespace": "{namespace}"
    },
    "type": "kubernetes.io/dockerconfigjson"
    }}]}"""
    dockerconfigjson = create_ccr_key_info(lcminfo, adminpassword)
    secret_string = secret_string.replace("{ccr_name}", ccr_name)
    secret_string = secret_string.replace("{base64string}", dockerconfigjson)
    secret_string = secret_string.replace("{namespace}", namespace)
    logger.info(secret_string)
    secretfile = ccrpath + "/" + ccr_name.strip() + ".json"
    _write_string_to_file(secretfile, secret_string)
    return secretfile


def replace_line_in_yaml_file(yamlPath, **replacedata):
    try:
        with open(yamlPath, 'r', encoding="utf-8") as f:
            lines = f.readlines()
            f.close()
        for index in range(len(lines)):
            for key in replacedata:
                tempkey = key + ":"
                if (tempkey in lines[index]) and ("#" not in lines[index]):
                    if ('urlNms' in tempkey):
                        lines[index + 1] = "  - " + replacedata[key] + "\n"
                    else:
                        strs = lines[index].split(':')
                        tempstr = strs[0].strip()
                        if key == tempstr:
                            lines[index] = strs[0] + ": " + replacedata[key] + "\n"
                            print(lines[index])
        with open(yamlPath, 'w', encoding="utf-8") as f:
            f.seek(0)
            f.writelines(lines)
            f.close()
    except Exception as e:
        logger.info("modify yaml file Fail.")
        logger.info(e)


def create_ccr_pnp_vcu_vdu_scfplan_file(toolpath, testlinepath, deployplanname, cloudid,
                                        swversion, namespace, clusterchart, clusteryaml,
                                        prerequisitechart, prerequisiteyaml, mainchart, mainyaml, secretname,
                                        pnpscffile, productname, ccr_secret_name, container_registries,
                                        addationalta, artifactory_location="HZ"):
    try:
        tool_path = get_conversion_tool(swversion, toolpath, artifactory_location)
        logger.info(tool_path)
        product_name_lower = productname.strip().lower()
        new_clusteryaml = conversion_yaml_file(tool_path, clusteryaml, "cluster", product_name_lower)
        new_prerequisiteyaml = conversion_yaml_file(tool_path, prerequisiteyaml, "prerequisite", product_name_lower)
        new_mainyaml = conversion_yaml_file(tool_path, mainyaml, " ", product_name_lower)
        replacedata = {"restoreData": "false"}
        replace_line_in_yaml_file(new_prerequisiteyaml, **replacedata)
        clusterbase64 = _get_encode_base64(new_clusteryaml)
        prerequisitebase64 = _get_encode_base64(new_prerequisiteyaml)
        mainbase64 = _get_encode_base64(new_mainyaml)
        pnpscfpartstring = _get_pnp_scf_part_string(pnpscffile, swversion)
        result = create_ccr_pnp_netact_deploy_plan(testlinepath, product_name_lower, deployplanname, cloudid,
                                                   swversion, namespace, clusterchart, clusterbase64,
                                                   prerequisitechart, prerequisitebase64, mainchart, mainbase64,
                                                   secretname, pnpscfpartstring, ccr_secret_name, container_registries,
                                                   addationalta)
    except Exception as e:
        logger.info("create the scf plan fail")
        logger.info(e)
    finally:
        delete_conversion_tool(tool_path)
    return result


def create_ccr_pnp_netact_deploy_plan(storeplanpath, productname, deployplanname, cloudid,
                                      swversion, namespace, clusterchart, clusterbase64,
                                      prerequisitechart, prerequisitebase64, mainchart, mainbase64,
                                      secretname, pnpscfstring, ccr_secret_name, container_registries,
                                      addationalta):
    templatestring = _get_pnp_scfplan_template_string()
    templatestring = templatestring.replace("image-registry.openshift-image-registry.svc:5000/{namespacestring}", container_registries)
    if len(templatestring) < 5:
        logger.info("can not read the template file")
        return ""
    if not os.path.exists(storeplanpath):
        logger.info("there are not the storing path: {}".format(storeplanpath))
        return ""
    if addationalta is None:
        if ccr_secret_name is None:
            tempsecretname = secretname
        else:
            tempsecretname = secretname + """</p>\n        <p>""" + ccr_secret_name
    else:
        if ccr_secret_name is None:
            tempsecretname = secretname + """</p>\n        <p>""" + addationalta
        else:
            tempsecretname = secretname + """</p>\n        <p>""" + addationalta
            tempsecretname = tempsecretname + """</p>\n        <p>""" + ccr_secret_name

    logger.info("The plan storing path is {}".format(storeplanpath))
    templatestring = templatestring.format(planname=deployplanname, cloudid=cloudid, swversion=swversion, productname=productname,
                                           namespacestring=namespace, clusterchart=clusterchart, clusterbase64=clusterbase64,
                                           prerequisitechart=prerequisitechart, prerequisitebase64=prerequisitebase64,
                                           mainchart=mainchart, mainbase64=mainbase64, secretname=tempsecretname, pnpscfpart=pnpscfstring)
    logger.info(templatestring)
    storename = storeplanpath + """/""" + deployplanname.strip() + """.xml"""
    logger.info(storename)
    _write_string_to_file(storename, templatestring)
    return storename


def _download_scf_conversion_tool(swversion, temppath):
    try:
        if os.path.exists(temppath):
            shutil.rmtree(temppath)
        os.makedirs(temppath)
        tempstring = """https://artifactory-hz1.int.net.nokia.com/artifactory/mnp5g-central-public-remote/System_Release/"""
        wgetpathurl = tempstring + """{0}/{1}/{2}_migtools_linux.tgz"""
        wgetoutpath = temppath + """/{0}_migtools_linux.tgz"""
        swversionlist = swversion.split('_')
        productrelease = swversionlist[0].strip()
        wgetpathurl = wgetpathurl.format(productrelease, swversion, swversion)
        wgetoutpath = wgetoutpath.format(swversion)
        logger.info(wgetpathurl)
        file_name = artifactory._download_file_from_artifactory(wgetpathurl, wgetoutpath)
        time.sleep(2)
        logger.info(file_name)
        return file_name
    except Exception as e:
        raise Exception("can not download conversion tool")
        logger.info(e)
        return ""


def get_scf_conversion_tool(swversion, toolpath):
    unique_id = time.strftime("%Y%m%d_%H%M%S", time.localtime())
    currenttoolpath = os.path.join(toolpath, unique_id)
    temppath = os.path.join(currenttoolpath, "scfconversiontool")
    conversiontoolname = _download_scf_conversion_tool(swversion, temppath)
    if _uncompress_tar_file(conversiontoolname, temppath):
        return currenttoolpath
    else:
        return None


def conversion_scf_file(toolpath, oldscffile, productstyle, newscffilepath):
    temppath = os.path.join(toolpath, "scfconversiontool")
    application = temppath + """/migtools_cli.sh"""
    tempfilestring = (os.path.basename(oldscffile)).split('.')
    logger.info(tempfilestring[0])
    newscffile = newscffilepath.strip() + tempfilestring[0] + """_new.xml"""
    feedbackfile = newscffilepath.strip() + """feedback.json"""
    command = """{application} {productstyle} {oldscffile} {newscffile} {feedbackfile}"""
    tool_style = productstyle.strip().lower()
    command = command.format(application=application, productstyle=tool_style, oldscffile=oldscffile,
                             newscffile=newscffile, feedbackfile=feedbackfile)
    logger.info(command)
    os.system(command)
    time.sleep(10)
    return newscffile


def rebuild_scf_file_for_pnp_part(scffilename, btsid):
    linestring = """      <p name="AutoConnSiteID">MRBTS-{{btsid}}</p>
      <p name="$maintenanceRegionId">PNP</p>
      <p name="$maintenanceRegionCId">1</p>\n"""
    replaceLineString = linestring.replace('{{btsid}}', str(btsid))
    logger.info(linestring)
    try:
        num_lines = 6
        with open(scffilename, 'r') as file:
            lines = file.readlines()
        remaining_lines = lines[num_lines:-2]
        remaining_lines[1] = remaining_lines[1] + replaceLineString
        file_name = scffilename + """_part"""
        logger.info(file_name)
        with open(file_name, 'w') as file:
            file.writelines(remaining_lines)
        filename = os.path.basename(scffilename) + """_part"""
        logger.info(filename)
        return filename
    except Exception as e:
        raise Exception("rebuild the SCF File Fail.")
        logger.info(e)
        return ""


def get_newversion_scf_pnp_part_file(swversion, oldscffile, newscffilepath, toolpath='/home/ute'):
    try:
        tempversion = swversion.strip().lower()
        logger.info(tempversion)
        if tempversion.find('vcu') != -1:
            productstyle = 'vcu'
        elif tempversion.find('vdu') != -1:
            productstyle = 'vdu'
        else:
            raise ValueError('Either `vcu` or `vdu` must be defined.')
        logger.info(productstyle)
        currenttoolpath = get_scf_conversion_tool(swversion, toolpath)
        logger.info(currenttoolpath)
        newscffile = conversion_scf_file(currenttoolpath, oldscffile, productstyle, newscffilepath)
        logger.info(newscffile)
        return newscffile
    except Exception as e:
        logger.info(e)
    finally:
        if currenttoolpath is not None:
            delete_conversion_tool(currenttoolpath)
    return ""
